mapper.select:
SELECT fin_statement_ln_id, fin_statement_hd_id, line_type, line_seq_number, fin_statement_item_name, fin_statement_item_type, amount as amount, adj_amount, adj_reason, final_amount, account_code FROM hls_fin_statement_ln
fin_statement_hd_id= #{finStatementHdId}
AND line_type=#{lineType}
ORDER BY line_seq_number ASC

SELECT count(*) as total FROM  hls_fin_statement_ln


        fin_statement_hd_id= #{finStatementHdId}


        AND line_type=#{lineType}

SELECT  max(distinct header_id) as header_id
FROM  hls_fin_statement_ln


        fin_statement_hd_id= #{finStatementHdId}


        AND line_type=#{lineType}

SELECT line_seq_number, header_id, attribute_1, attribute_2, attribute_3 * 100, ( CASE WHEN trim(attribute_2) IN ( '权益乘数', '营运资本', '存货周转天数','利息保障倍数', '应收账款周转天数', '营业周期', '净营业周期', '现金流量利息保障倍数', '权益乘数') THEN attribute_3 * 1 ELSE attribute_3 * 1 end ) attribute_3, (CASE WHEN trim(attribute_2) IN ( '权益乘数', '营运资本', '存货周转天数','利息保障倍数', '应收账款周转天数', '营业周期', '净营业周期', '现金流量利息保障倍数', '权益乘数' ) THEN attribute_4 * 1 ELSE attribute_4 * 1 end )attribute_4, (CASE WHEN trim(attribute_2) IN ( '权益乘数', '营运资本', '存货周转天数','利息保障倍数', '应收账款周转天数', '营业周期', '净营业周期', '现金流量利息保障倍数', '权益乘数' ) THEN attribute_5 * 1 ELSE attribute_5 * 1 end )attribute_5, (CASE WHEN trim(attribute_2) IN ( '权益乘数', '营运资本', '存货周转天数','利息保障倍数', '应收账款周转天数', '营业周期', '净营业周期', '现金流量利息保障倍数', '权益乘数' ) THEN attribute_6 * 1 ELSE attribute_6 * 1 end )AS attribute_6 FROM hls_fin_statement_ln where header_id = #{headerId} and line_type = #{lineType}
and attribute_1 in ('成长能力指标分析', '营运能力指标分析', '盈利能力指标分析', '偿债能力指标分析')
and attribute_1 = #{attribute_1}
order by line_seq_number
